        ["Máximo (255)"] = ("Maximum (255)", "最大 (255)", "Maximum (255)", "Maximum (255)", "Massimo (255)", "最大 (255)", "최대 (255)", "Máximo (255)"),
        ["Objeto"] = ("Item", "道具", "Objet", "Item", "Strumento", "どうぐ", "도구", "Item"),
        ["Amistad"] = ("Friendship", "亲密度", "Amitié", "Freundschaft", "Amicizia", "なつき度", "친밀도", "Amizade"),
        ["— Sin objeto —"] = ("— No item —", "— 无道具 —", "— Aucun objet —", "— Kein Item —", "— Nessuno strumento —", "— どうぐなし —", "— 도구 없음 —", "— Sem item —"),
        ["Escribe el nombre de un objeto para buscarlo y equiparlo."] = ("Type an item’s name to find and equip it.", "输入道具名称即可查找并携带。", "Tapez le nom d’un objet pour le trouver et l’équiper.", "Gib den Namen eines Items ein, um es zu finden und auszurüsten.", "Digita il nome di uno strumento per trovarlo e assegnarlo.", "どうぐの名前を入力すると、検索して持たせることができます。", "도구 이름을 입력해 찾아서 지니게 하세요.", "Digite o nome de um item para encontrá-lo e equipá-lo."),
        ["Ya está equipado. «Quitar» lo devuelve a la bolsa."] = ("Already equipped. “Remove” returns it to the bag.", "已携带。点击“取下”可放回背包。", "Déjà équipé. « Retirer » le remet dans le sac.", "Bereits ausgerüstet. „Abnehmen“ legt es zurück in den Beutel.", "Già assegnato. «Togli» lo rimette nello zaino.", "すでに持っています。「外す」でバッグに戻します。", "이미 지니고 있습니다. ‘빼기’를 누르면 가방으로 돌아갑니다.", "Já está equipado. “Remover” devolve o item à mochila."),
        ["Lo lleva {0}. Retíralo de ese Pokémon para usarlo aquí."] = ("{0} is holding it. Take it from that Pokémon to use it here.", "{0} 正在携带。请先从那只宝可梦取下才能在此使用。", "{0} le tient. Retirez-le de ce Pokémon pour l’utiliser ici.", "{0} trägt es. Nimm es diesem Pokémon ab, um es hier zu verwenden.", "Lo tiene {0}. Toglilo a quel Pokémon per usarlo qui.", "{0} が持っています。ここで使うには、そのポケモンから外してください。", "{0}이(가) 지니고 있습니다. 여기서 쓰려면 그 포켓몬에게서 빼세요.", "{0} está com ele. Remova-o desse Pokémon para usá-lo aqui."),
        ["Sin unidades. Usa «Bolsa» para agregar este objeto."] = ("None left. Use “Bag” to add this item.", "数量不足。请使用“背包”添加此道具。", "Aucune unité. Utilisez « Sac » pour ajouter cet objet.", "Keins vorhanden. Füge dieses Item über „Beutel“ hinzu.", "Nessuna unità. Usa «Zaino» per aggiungere questo strumento.", "数がありません。「バッグ」でこのどうぐを追加してください。", "수량이 없습니다. ‘가방’에서 이 도구를 추가하세요.", "Sem unidades. Use “Mochila” para adicionar este item."),
        ["En la bolsa: {0}. {1}"] = ("In the bag: {0}. {1}", "背包中：{0}。{1}", "Dans le sac : {0}. {1}", "Im Beutel: {0}. {1}", "Nello zaino: {0}. {1}", "バッグ内：{0}。{1}", "가방에 {0}개. {1}", "Na mochila: {0}. {1}"),
        ["Se asigna a un solo Pokémon."] = ("It goes to a single Pokémon.", "只能分配给一只宝可梦。", "S’attribue à un seul Pokémon.", "Geht an ein einziges Pokémon.", "Va a un solo Pokémon.", "1匹のポケモンだけに割り当てられます。", "포켓몬 한 마리에게만 지정됩니다.", "Vai para um único Pokémon."),
        ["Equipar toma una unidad; quitar la devuelve."] = ("Equipping takes one; removing returns it.", "携带时取走一个，取下时放回。", "Équiper en prend un ; retirer le rend.", "Ausrüsten nimmt eins aus dem Beutel, Abnehmen legt es zurück.", "Assegnare ne prende uno, togliere lo restituisce.", "持たせると 1個減り、外すと 1個戻ります。", "지니게 하면 1개 줄고, 빼면 1개 돌아옵니다.", "Equipar usa uma unidade; remover a devolve."),
        ["Objeto retirado y devuelto a la bolsa."] = ("Item removed and returned to the bag.", "道具已取下并放回背包。", "Objet retiré et remis dans le sac.", "Item abgenommen und zurück in den Beutel gelegt.", "Strumento tolto e rimesso nello zaino.", "どうぐを外してバッグに戻しました。", "도구를 빼서 가방으로 돌려보냈습니다.", "Item removido e devolvido à mochila."),
        ["{0} equipado en {1}."] = ("{0} equipped on {1}.", "{1} 已携带 {0}。", "{0} équipé sur {1}.", "{1} trägt jetzt {0}.", "{0} assegnato a {1}.", "{1} に {0} を持たせました。", "{1}에게 {0}을(를) 지니게 했습니다.", "{0} equipado em {1}."),

