        ["No hay objetos con ese filtro."] = ("No items match that filter.", "没有符合筛选条件的道具。", "Aucun objet ne correspond à ce filtre.", "Keine Items für diesen Filter.", "Nessuno strumento con questo filtro.", "この条件に合うどうぐはありません。", "이 조건에 맞는 도구가 없습니다.", "Nenhum item com esse filtro."),
        ["Prueba con otro nombre o categoría."] = ("Try another name or category.", "请尝试其他名称或类别。", "Essayez un autre nom ou une autre catégorie.", "Versuch es mit einem anderen Namen oder einer anderen Kategorie.", "Prova con un altro nome o categoria.", "別の名前やカテゴリーで試してください。", "다른 이름이나 카테고리로 검색해 보세요.", "Tente outro nome ou categoria."),
        ["En la partida: {0}  ·  Cantidad preparada: {1}  ·  Máximo: {2}"] = ("In the save: {0}  ·  Prepared quantity: {1}  ·  Maximum: {2}", "存档中：{0}  ·  准备数量：{1}  ·  最大：{2}", "Dans la partie : {0}  ·  Quantité préparée : {1}  ·  Maximum : {2}", "Im Spielstand: {0}  ·  Vorbereitete Menge: {1}  ·  Maximum: {2}", "Nella partita: {0}  ·  Quantità preparata: {1}  ·  Massimo: {2}", "セーブデータ内：{0}  ·  準備した数：{1}  ·  最大：{2}", "세이브: {0}  ·  준비한 수량: {1}  ·  최대: {2}", "No save: {0}  ·  Quantidade preparada: {1}  ·  Máximo: {2}"),
        ["Este objeto está equipado en un Pokémon."] = ("A Pokémon has this item equipped.", "有宝可梦正在携带此道具。", "Cet objet est équipé sur un Pokémon.", "Ein Pokémon trägt dieses Item.", "Questo strumento è assegnato a un Pokémon.", "このどうぐはポケモンが持っています。", "포켓몬이 이 도구를 지니고 있습니다.", "Este item está equipado em um Pokémon."),
        ["Agregar suma a lo que tienes. Fijar cantidad establece el total; 0 lo retira de la bolsa."] = ("Add puts more on top of what you have. Set quantity fixes the total; 0 removes it from the bag.", "“添加”会在现有数量上增加。“设定数量”直接设为总数；设为 0 会从背包移除。", "Ajouter s’additionne à ce que vous avez. Fixer la quantité établit le total ; 0 le retire du sac.", "Hinzufügen addiert zum Bestand, Menge festlegen setzt die Gesamtzahl; 0 entfernt es.", "Aggiungi somma a ciò che hai. Imposta quantità fissa il totale; 0 lo toglie dallo zaino.", "「追加」は今の数に足します。「数を設定」は合計を指定します。0 にするとバッグから取り除きます。", "‘추가’는 현재 수량에 더합니다. ‘수량 지정’은 총수량을 정합니다. 0이면 가방에서 제거합니다.", "Adicionar soma ao que você tem. Definir quantidade fixa o total; 0 remove o item da mochila."),
        ["No se agregaron unidades; revisa la cantidad y el máximo."] = ("Nothing was added; check the quantity and the maximum.", "未添加任何数量；请检查数量和上限。", "Rien n’a été ajouté ; vérifiez la quantité et le maximum.", "Nichts hinzugefügt. Prüfe die Menge und das Maximum.", "Nessuna unità aggiunta: controlla la quantità e il massimo.", "追加されませんでした。数と上限を確認してください。", "추가되지 않았습니다. 수량과 최대치를 확인하세요.", "Nenhuma unidade adicionada; revise a quantidade e o máximo."),
        ["{0}: agregadas {1} unidades."] = ("{0}: {1} added.", "{0}：已添加 {1} 个。", "{0} : {1} ajoutés.", "{0}: {1} hinzugefügt.", "{0}: aggiunte {1} unità.", "{0}：{1}個追加しました。", "{0}: {1}개 추가했습니다.", "{0}: {1} unidades adicionadas."),
