        ["Marcar todos vistos"] = ("Mark all seen", "全部标记为已见过", "Tout marquer vu", "Alle als gesehen markieren", "Segna tutti come visti", "すべて見つけた状態にする", "모두 발견으로 표시", "Marcar todos como vistos"),
