        ["Aún no hay respaldos."] = ("No backups yet.", "还没有备份。", "Aucune copie pour le moment.", "Noch keine Sicherungen.", "Ancora nessun backup.", "バックアップはまだありません。", "아직 백업이 없습니다.", "Ainda não há backups."),
        ["Sin detalles"] = ("No details", "没有详细信息", "Aucun détail", "Keine Details", "Nessun dettaglio", "詳細なし", "상세 정보 없음", "Sem detalhes"),
