        ["1 diferencia."] = ("1 difference.", "1 处差异。", "1 différence.", "1 Unterschied.", "1 differenza.", "相違点 1件。", "차이점 1개.", "1 diferença."),
        ["{0} diferencias."] = ("{0} differences.", "{0} 处差异。", "{0} différences.", "{0} Unterschiede.", "{0} differenze.", "相違点 {0}件。", "차이점 {0}개.", "{0} diferenças."),
        ["Elige dos partidas del mismo juego."] = ("Choose two saves of the same game.", "请选择同一款游戏的两个存档。", "Choisissez deux parties du même jeu.", "Wähle zwei Spielstände desselben Spiels.", "Scegli due partite dello stesso gioco.", "同じゲームのセーブデータを 2つ選んでください。", "같은 게임의 세이브 두 개를 선택하세요.", "Escolha dois saves do mesmo jogo."),
        ["Esas partidas son de juegos distintos: {0} y {1}."] = ("Those saves are from different games: {0} and {1}.", "这些存档来自不同的游戏：{0} 和 {1}。", "Ces parties viennent de jeux différents : {0} et {1}.", "Diese Spielstände gehören zu verschiedenen Spielen: {0} und {1}.", "Queste partite sono di giochi diversi: {0} e {1}.", "それらのセーブデータは別のゲームのものです：{0} と {1}。", "두 세이브는 서로 다른 게임의 것입니다: {0}, {1}.", "Esses saves são de jogos diferentes: {0} e {1}."),
        ["No hay diferencias en Pokémon, dinero ni objetos."] = ("No differences in Pokémon, money or items.", "宝可梦、金钱和道具都没有差异。", "Aucune différence de Pokémon, d’argent ou d’objets.", "Keine Unterschiede bei Pokémon, Geld oder Items.", "Nessuna differenza in Pokémon, soldi o strumenti.", "ポケモン、おこづかい、どうぐに相違はありません。", "포켓몬, 돈, 도구에 차이가 없습니다.", "Não há diferenças em Pokémon, dinheiro nem itens."),
        ["(vacío)"] = ("(empty)", "（空）", "(vide)", "(leer)", "(vuoto)", "（空）", "(비어 있음)", "(vazio)"),
        ["Otros datos"] = ("Other data", "其他数据", "Autres données", "Sonstige Daten", "Altri dati", "その他のデータ", "기타 데이터", "Outros dados"),
        ["Objetos clave"] = ("Key items", "重要道具", "Objets rares", "Basis-Items", "Strumenti base", "だいじなもの", "중요한 도구", "Itens-chave"),
        ["Objetos del PC"] = ("PC items", "电脑中的道具", "Objets du PC", "Items im PC", "Strumenti nel PC", "パソコンのどうぐ", "PC의 도구", "Itens do PC"),
        ["Poké Ball"] = ("Poké Ball", "精灵球", "Poké Ball", "Pokéball", "Poké Ball", "モンスターボール", "몬스터볼", "Pokébola"),
        ["Legalidad"] = ("LEGALITY", "合法性", "LÉGALITÉ", "LEGALITÄT", "LEGALITÀ", "正規判定", "합법성", "LEGALIDADE"),
        ["Esta partida no permite reorganizar sus Pokémon."] = ("This save does not allow its Pokémon to be rearranged.", "此存档不支持重新整理宝可梦。", "Cette sauvegarde ne permet pas de réorganiser ses Pokémon.", "Dieser Spielstand erlaubt nicht, seine Pokémon umzusortieren.", "Questa partita non permette di riordinare i suoi Pokémon.", "このセーブデータではポケモンを並べ替えできません。", "이 세이브는 포켓몬을 다시 정리할 수 없습니다.", "Este save não permite reorganizar seus Pokémon."),
        ["Ese lugar no se puede usar."] = ("That place cannot be used.", "无法使用该位置。", "Cet emplacement est inutilisable.", "Dieser Platz kann nicht verwendet werden.", "Quella posizione non si può usare.", "その場所は使えません。", "그 위치는 사용할 수 없습니다.", "Esse local não pode ser usado."),
        ["El juego aún no ha abierto esa caja."] = ("The game has not opened that box yet.", "游戏尚未开放该盒子。", "Le jeu n'a pas encore ouvert cette boîte.", "Das Spiel hat diese Box noch nicht freigeschaltet.", "Il gioco non ha ancora aperto quel box.", "そのボックスはゲーム内でまだ開放されていません。", "게임에서 아직 열리지 않은 박스입니다.", "O jogo ainda não abriu essa caixa."),
        ["Ese lugar ya está ocupado."] = ("That place is already taken.", "该位置已被占用。", "Cet emplacement est déjà occupé.", "Dieser Platz ist bereits belegt.", "Quella posizione è già occupata.", "その場所はすでに使われています。", "그 위치는 이미 사용 중입니다.", "Esse local já está ocupado."),
        ["{0} lleva una carta. Quítasela en el juego antes de cambiarlo de lugar."] = ("{0} is holding mail. Take it away in the game before moving it.", "{0} 携带着信件。请先在游戏中取下再移动。", "{0} porte une lettre. Retirez-la dans le jeu avant de le déplacer.", "{0} trägt einen Brief. Nimm ihn im Spiel ab, bevor du es verschiebst.", "{0} tiene un messaggio. Toglilo nel gioco prima di spostarlo.", "{0} はメールを持っています。移動する前にゲーム内で外してください。", "{0}이(가) 메일을 지니고 있습니다. 옮기기 전에 게임에서 빼세요.", "{0} está com uma carta. Retire-a no jogo antes de mudá-lo de lugar."),
        ["{0} es tu compañero inicial y debe quedarse donde está."] = ("{0} is your starter partner and has to stay where it is.", "{0} 是你的初始伙伴，必须留在原位。", "{0} est votre partenaire de départ et doit rester à sa place.", "{0} ist dein Partner-Pokémon und muss an seinem Platz bleiben.", "{0} è il tuo compagno iniziale e deve restare dov’è.", "{0} は最初のパートナーなので、移動できません。", "{0}은(는) 처음 함께한 파트너라서 그 자리에 있어야 합니다.", "{0} é seu parceiro inicial e deve ficar onde está."),
        ["{0} está en un equipo de combate. Sácalo de ahí en el juego antes de cambiarlo de lugar."] = ("{0} is in a battle team. Take it out in the game before moving it.", "{0} 在对战队伍中。请先在游戏中移出再移动。", "{0} fait partie d'une équipe de combat. Retirez-le dans le jeu avant de le déplacer.", "{0} ist in einem Kampfteam. Nimm es im Spiel heraus, bevor du es verschiebst.", "{0} è in una squadra di lotta. Toglilo nel gioco prima di spostarlo.", "{0} はバトルチームに入っています。移動する前にゲーム内で外してください。", "{0}은(는) 배틀팀에 들어 있습니다. 옮기기 전에 게임에서 빼세요.", "{0} está em uma equipe de batalha. Tire-o dela no jogo antes de mudá-lo de lugar."),
        ["El equipo ya tiene seis Pokémon."] = ("The team already has six Pokémon.", "队伍已有六只宝可梦。", "L'équipe compte déjà six Pokémon.", "Das Team hat bereits sechs Pokémon.", "La squadra ha già sei Pokémon.", "手持ちはすでに 6匹です。", "지닌 포켓몬이 이미 6마리입니다.", "A equipe já tem seis Pokémon."),
        ["El equipo debe conservar al menos un Pokémon que no sea un huevo."] = ("The team must keep at least one Pokémon that is not an egg.", "队伍中至少要保留一只不是蛋的宝可梦。", "L'équipe doit garder au moins un Pokémon qui ne soit pas un œuf.", "Das Team muss mindestens ein Pokémon behalten, das kein Ei ist.", "La squadra deve conservare almeno un Pokémon che non sia un uovo.", "手持ちにはタマゴ以外のポケモンを少なくとも 1匹残す必要があります。", "지닌 포켓몬에 알이 아닌 포켓몬을 한 마리 이상 남겨야 합니다.", "A equipe deve manter pelo menos um Pokémon que não seja um ovo."),
        ["El equipo tiene datos dañados y no se puede reorganizar."] = ("The team has damaged data and cannot be rearranged.", "队伍数据已损坏，无法重新整理。", "L'équipe contient des données endommagées et ne peut pas être réorganisée.", "Das Team hat beschädigte Daten und kann nicht umsortiert werden.", "La squadra ha dati danneggiati e non si può riordinare.", "手持ちのデータが破損しているため、並べ替えできません。", "지닌 포켓몬의 데이터가 손상되어 다시 정리할 수 없습니다.", "A equipe tem dados danificados e não pode ser reorganizada."),
        ["{0} va a {1}. Guarda para aplicarlo."] = ("{0} goes to {1}. Save to apply it.", "{0} 移至 {1}。保存后生效。", "{0} va en {1}. Enregistrez pour l'appliquer.", "{0} kommt nach {1}. Zum Anwenden speichern.", "{0} va in {1}. Salva per applicarlo.", "{0} を {1} へ移動します。保存すると適用されます。", "{0}을(를) {1}(으)로 옮깁니다. 저장하면 적용됩니다.", "{0} vai para {1}. Salve para aplicar."),
        ["{0} y {1} cambian de lugar. Guarda para aplicarlo."] = ("{0} and {1} swap places. Save to apply it.", "{0} 和 {1} 交换了位置。保存后生效。", "{0} et {1} échangent leur place. Enregistrez pour l'appliquer.", "{0} und {1} tauschen die Plätze. Zum Anwenden speichern.", "{0} e {1} si scambiano di posto. Salva per applicarlo.", "{0} と {1} の場所を入れ替えます。保存すると適用されます。", "{0}와(과) {1}의 위치를 바꿉니다. 저장하면 적용됩니다.", "{0} e {1} trocam de lugar. Salve para aplicar."),
        ["{0} está en tu equipo. Cámbialo en el juego antes de borrarlo."] = ("{0} is in your team. Replace it in the game before deleting it.", "{0} 在你的队伍中。请先在游戏中换下再删除。", "{0} est dans votre équipe. Remplacez-le dans le jeu avant de le supprimer.", "{0} ist in deinem Team. Ersetze es im Spiel, bevor du es löschst.", "{0} è nella tua squadra. Sostituiscilo nel gioco prima di eliminarlo.", "{0} は手持ちにいます。削除する前にゲーム内で入れ替えてください。", "{0}은(는) 지닌 포켓몬입니다. 지우기 전에 게임에서 교체하세요.", "{0} está na sua equipe. Troque-o no jogo antes de apagá-lo."),
        ["{0} borrado y {1} devuelto a la bolsa. Guarda para aplicarlo o deshazlo con clic derecho."] = ("{0} deleted and {1} back in the bag. Save to apply it, or undo it with a right click.", "已删除 {0}，{1} 已放回背包。保存后生效，或右键撤销。", "{0} supprimé et {1} rendu au sac. Enregistrez pour l'appliquer ou annulez d'un clic droit.", "{0} gelöscht und {1} zurück in den Beutel gelegt. Zum Anwenden speichern oder per Rechtsklick rückgängig machen.", "{0} eliminato e {1} rimesso nello zaino. Salva per applicarlo o annullalo con il clic destro.", "{0} を削除し、{1} をバッグに戻しました。保存すると適用されます。右クリックで元に戻せます。", "{0}을(를) 지우고 {1}을(를) 가방에 돌려놓았습니다. 저장하면 적용되며, 오른쪽 클릭으로 되돌릴 수 있습니다.", "{0} apagado e {1} devolvido à mochila. Salve para aplicar ou desfaça com o botão direito."),
        ["{0} borrado. Guarda para aplicarlo o deshazlo con clic derecho."] = ("{0} deleted. Save to apply it, or undo it with a right click.", "已删除 {0}。保存后生效，或右键撤销。", "{0} supprimé. Enregistrez pour l'appliquer ou annulez d'un clic droit.", "{0} gelöscht. Zum Anwenden speichern oder per Rechtsklick rückgängig machen.", "{0} eliminato. Salva per applicarlo o annullalo con il clic destro.", "{0} を削除しました。保存すると適用されます。右クリックで元に戻せます。", "{0}을(를) 지웠습니다. 저장하면 적용되며, 오른쪽 클릭으로 되돌릴 수 있습니다.", "{0} apagado. Salve para aplicar ou desfaça com o botão direito."),
        ["{0} lleva {1}, que solo puede tener un Pokémon. Retíralo antes de clonarlo."] = ("{0} is holding {1}, which only one Pokémon can have. Take it off before cloning.", "{0} 携带着 {1}，它只能由一只宝可梦持有。请先取下再克隆。", "{0} porte {1}, qu'un seul Pokémon peut avoir. Retirez-le avant de le cloner.", "{0} trägt {1}, das nur ein Pokémon haben kann. Nimm es vor dem Klonen ab.", "{0} tiene {1}, che può avere un solo Pokémon. Toglilo prima di clonarlo.", "{0} は 1匹しか持てない {1} を持っています。クローンする前に外してください。", "{0}이(가) 한 마리만 지닐 수 있는 {1}을(를) 지니고 있습니다. 복제하기 전에 빼세요.", "{0} está com {1}, que só um Pokémon pode ter. Remova-o antes de clonar."),
        ["{0} clonado en {1}. Guarda para aplicarlo."] = ("{0} cloned to {1}. Save to apply it.", "已将 {0} 克隆到 {1}。保存后生效。", "{0} cloné en {1}. Enregistrez pour l'appliquer.", "{0} nach {1} geklont. Zum Anwenden speichern.", "{0} clonato in {1}. Salva per applicarlo.", "{0} を {1} にクローンしました。保存すると適用されます。", "{0}을(를) {1}에 복제했습니다. 저장하면 적용됩니다.", "{0} clonado em {1}. Salve para aplicar."),
        ["{0} clonado en {1} sin {2}, porque no hay otra unidad en la bolsa. Guarda para aplicarlo."] = ("{0} cloned to {1} without {2}, as the bag has no other. Save to apply it.", "已将 {0} 克隆到 {1}，但没有 {2}，因为背包里没有多余的。保存后生效。", "{0} cloné en {1} sans {2}, car le sac n'en a plus. Enregistrez pour l'appliquer.", "{0} ohne {2} nach {1} geklont, weil der Beutel keins mehr hat. Zum Anwenden speichern.", "{0} clonato in {1} senza {2}, perché nello zaino non ce n’è un altro. Salva per applicarlo.", "バッグに予備がないため、{0} を {2} なしで {1} にクローンしました。保存すると適用されます。", "가방에 여분이 없어 {0}을(를) {2} 없이 {1}에 복제했습니다. 저장하면 적용됩니다.", "{0} clonado em {1} sem {2}, pois não há outra unidade na mochila. Salve para aplicar."),
        ["{0} importado en {1}."] = ("{0} imported to {1}.", "已将 {0} 导入到 {1}。", "{0} importé en {1}.", "{0} nach {1} importiert.", "{0} importato in {1}.", "{0} を {1} にインポートしました。", "{0}을(를) {1}에 가져왔습니다.", "{0} importado em {1}."),
        ["{0} convertido de {1} a {2} e importado en {3}."] = ("{0} converted from {1} to {2} and imported to {3}.", "已将 {0} 从 {1} 转换为 {2} 并导入到 {3}。", "{0} converti de {1} en {2} et importé en {3}.", "{0} von {1} zu {2} konvertiert, jetzt in {3}.", "{0} convertito da {1} a {2} e importato in {3}.", "{0} を {1} から {2} に変換し、{3} にインポートしました。", "{0}을(를) {1}에서 {2}(으)로 변환해 {3}에 가져왔습니다.", "{0} convertido de {1} para {2} e importado em {3}."),
        ["Guarda para aplicarlo."] = ("Save to apply it.", "保存后生效。", "Enregistrez pour l'appliquer.", "Zum Anwenden speichern.", "Salva per applicarlo.", "保存すると適用されます。", "저장하면 적용됩니다.", "Salve para aplicar."),
        ["Llega sin {0}: no hay en la bolsa. Guarda para aplicarlo."] = ("It arrives without {0}, as the bag has none. Save to apply it.", "它没有携带 {0}，因为背包里没有。保存后生效。", "Il arrive sans {0}, car le sac n'en a pas. Enregistrez pour l'appliquer.", "Ohne {0}: nicht im Beutel. Zum Anwenden speichern.", "Arriva senza {0}, perché nello zaino non ce n’è. Salva per applicarlo.", "バッグにないため {0} なしで追加されます。保存すると適用されます。", "가방에 없어서 {0} 없이 도착합니다. 저장하면 적용됩니다.", "Chega sem {0}: não há na mochila. Salve para aplicar."),
        ["No se pudo leer ese archivo."] = ("That file could not be read.", "无法读取该文件。", "Impossible de lire ce fichier.", "Diese Datei konnte nicht gelesen werden.", "Impossibile leggere quel file.", "そのファイルを読み込めませんでした。", "그 파일을 읽을 수 없습니다.", "Não foi possível ler esse arquivo."),
        ["Ese archivo no contiene un Pokémon válido."] = ("That file does not hold a valid Pokémon.", "该文件不包含有效的宝可梦。", "Ce fichier ne contient pas de Pokémon valide.", "Diese Datei enthält kein gültiges Pokémon.", "Quel file non contiene un Pokémon valido.", "そのファイルに有効なポケモンのデータがありません。", "그 파일에 올바른 포켓몬이 없습니다.", "Esse arquivo não contém um Pokémon válido."),
        ["Las partidas japonesas de Game Boy no se mezclan con las de otros idiomas."] = ("Japanese Game Boy saves do not mix with those of other languages.", "日版 Game Boy 存档不能与其他语言版本互通。", "Les sauvegardes japonaises Game Boy ne se mélangent pas avec les autres langues.", "Japanische Game-Boy-Spielstände lassen sich nicht mit denen anderer Sprachen mischen.", "Le partite giapponesi per Game Boy non si mescolano con quelle di altre lingue.", "日本語版ゲームボーイのセーブデータは、ほかの言語のものと混在できません。", "일본판 게임보이 세이브는 다른 언어의 세이브와 섞을 수 없습니다.", "Os saves japoneses de Game Boy não se misturam com os de outros idiomas."),
        ["{0} no existe en {1}."] = ("{0} does not exist in {1}.", "{1} 中没有 {0}。", "{0} n'existe pas dans {1}.", "{0} gibt es in {1} nicht.", "{0} non esiste in {1}.", "{1} に {0} はいません。", "{1}에는 {0}이(가) 없습니다.", "{0} não existe em {1}."),
        ["Esa forma de {0} no se puede llevar a {1}."] = ("That form of {0} cannot go to {1}.", "{0} 的该形态无法转移到 {1}。", "Cette forme de {0} ne peut pas aller dans {1}.", "Diese Form von {0} kann nicht nach {1}.", "Quella forma di {0} non può andare in {1}.", "{0} のそのフォルムは {1} に連れて行けません。", "{0}의 그 폼은 {1}(으)로 옮길 수 없습니다.", "Essa forma de {0} não pode ir para {1}."),
        ["Un Pokémon de {0} no se puede llevar a {1}."] = ("A {0} Pokémon cannot go to {1}.", "{0} 格式的宝可梦无法转移到 {1}。", "Un Pokémon {0} ne peut pas aller dans {1}.", "Ein {0}-Pokémon kann nicht nach {1}.", "Un Pokémon di {0} non può andare in {1}.", "{0} のポケモンは {1} に連れて行けません。", "{0} 포켓몬은 {1}(으)로 옮길 수 없습니다.", "Um Pokémon de {0} não pode ir para {1}."),
        ["Ese Pokémon tiene datos que {0} no admite."] = ("That Pokémon has data {0} cannot hold.", "该宝可梦含有 {0} 不支持的数据。", "Ce Pokémon a des données que {0} n'accepte pas.", "Dieses Pokémon hat Daten, die {0} nicht unterstützt.", "Quel Pokémon ha dati che {0} non supporta.", "そのポケモンには {0} で扱えないデータがあります。", "그 포켓몬에는 {0}에서 지원하지 않는 데이터가 있습니다.", "Esse Pokémon tem dados que {0} não aceita."),
        ["{0} ordenada. Guarda para aplicarlo."] = ("{0} sorted. Save to apply it.", "{0} 已整理。保存后生效。", "{0} triée. Enregistrez pour l'appliquer.", "{0} sortiert. Zum Anwenden speichern.", "{0} ordinato. Salva per applicarlo.", "{0} を整理しました。保存すると適用されます。", "{0} 정리 완료. 저장하면 적용됩니다.", "{0} organizada. Salve para aplicar."),
        ["Ordenar caja por Pokédex"] = ("Sort box by Pokédex", "按图鉴排列盒子", "Trier la boîte par Pokédex", "Box nach Pokédex sortieren", "Ordina il box per Pokédex", "ボックスを図鑑順に整理", "박스를 도감순으로 정리", "Ordenar caixa por Pokédex"),
        ["Ordenar caja por nivel"] = ("Sort box by level", "按等级排列盒子", "Trier la boîte par niveau", "Box nach Level sortieren", "Ordina il box per livello", "ボックスをレベル順に整理", "박스를 레벨순으로 정리", "Ordenar caixa por nível"),
        ["Ordenar caja por nombre"] = ("Sort box by name", "按名字排列盒子", "Trier la boîte par nom", "Box nach Name sortieren", "Ordina il box per nome", "ボックスを名前順に整理", "박스를 이름순으로 정리", "Ordenar caixa por nome"),
        ["Deshacer el último cambio de cajas"] = ("Undo the last box change", "撤销上一次盒子更改", "Annuler le dernier changement de boîtes", "Letzte Box-Änderung rückgängig machen", "Annulla l’ultima modifica ai box", "最後のボックスの変更を元に戻す", "마지막 박스 변경 되돌리기", "Desfazer a última alteração nas caixas"),
