        ["El portapapeles no tiene un set de Showdown."] = ("The clipboard has no Showdown set.", "剪贴板中没有 Showdown 配置。", "Le presse-papiers ne contient pas de set Showdown.", "Die Zwischenablage enthält kein Showdown-Set.", "Gli appunti non contengono un set di Showdown.", "クリップボードに Showdown のセットがありません。", "클립보드에 Showdown 세트가 없습니다.", "A área de transferência não tem um set do Showdown."),
        ["Ese set es de {0}, no de {1}."] = ("That set is for {0}, not {1}.", "该配置属于{0}，不是{1}。", "Ce set est pour {0}, pas pour {1}.", "Dieses Set ist für {0}, nicht für {1}.", "Quel set è per {0}, non per {1}.", "そのセットは {0} 用で、{1} 用ではありません。", "그 세트는 {1}이(가) 아니라 {0}의 세트입니다.", "Esse set é de {0}, não de {1}."),
        ["Set aplicado a {0}. Revísalo antes de guardar."] = ("Set applied to {0}. Review it before saving.", "配置已应用到{0}。保存前请检查。", "Set appliqué à {0}. Vérifiez-le avant d’enregistrer.", "Set auf {0} angewendet. Prüfe es vor dem Speichern.", "Set applicato a {0}. Controllalo prima di salvare.", "{0} にセットを適用しました。保存前に確認してください。", "{0}에 세트를 적용했습니다. 저장하기 전에 확인하세요.", "Set aplicado a {0}. Revise antes de salvar."),
        ["Set aplicado a {0}. No se aplicó: {1}."] = ("Set applied to {0}. Not applied: {1}.", "配置已应用到{0}。未应用：{1}。", "Set appliqué à {0}. Non appliqué : {1}.", "Set auf {0} angewendet. Nicht angewendet: {1}.", "Set applicato a {0}. Non applicato: {1}.", "{0} にセットを適用しました。適用されなかった項目：{1}。", "{0}에 세트를 적용했습니다. 적용되지 않은 항목: {1}.", "Set aplicado a {0}. Não aplicado: {1}."),
        ["El nivel debe estar entre 1 y {0}."] = ("The level must be between 1 and {0}.", "等级必须在 1 到 {0} 之间。", "Le niveau doit être compris entre 1 et {0}.", "Das Level muss zwischen 1 und {0} liegen.", "Il livello deve essere tra 1 e {0}.", "レベルは 1 から {0} の間にしてください。", "레벨은 1에서 {0} 사이여야 합니다.", "O nível deve estar entre 1 e {0}."),
