        ["Motivo"] = ("Reason", "原因", "Motif", "Grund", "Motivo", "理由", "사유", "Motivo"),
        ["Elige a quién y qué cambiar. Lo que un Pokémon no admita se omite y se explica aquí."] = ("Choose who and what to change. Anything a Pokémon can't take is skipped and explained here.", "选择对象和要更改的内容。宝可梦无法接受的更改会被跳过，并在此说明。", "Choisissez qui et quoi modifier. Ce qu’un Pokémon n’accepte pas est ignoré et expliqué ici.", "Wähle, wen und was du ändern willst. Was ein Pokémon nicht unterstützt, wird übersprungen und hier erklärt.", "Scegli chi e cosa cambiare. Ciò che un Pokémon non accetta viene saltato e spiegato qui.", "対象と変更内容を選んでください。ポケモンに適用できない内容はスキップし、ここに理由を表示します。", "대상과 변경할 내용을 고르세요. 포켓몬에게 적용할 수 없는 내용은 건너뛰고 여기에 설명합니다.", "Escolha quem e o que mudar. O que um Pokémon não aceitar é ignorado e explicado aqui."),
        ["Marca al menos un cambio."] = ("Tick at least one change.", "请至少勾选一项更改。", "Cochez au moins une modification.", "Markiere mindestens eine Änderung.", "Seleziona almeno una modifica.", "変更を少なくとも1つ選んでください。", "변경 사항을 하나 이상 선택하세요.", "Marque pelo menos uma alteração."),
        ["Ahí no hay ningún Pokémon."] = ("There are no Pokémon there.", "那里没有宝可梦。", "Il n’y a aucun Pokémon ici.", "Dort ist kein Pokémon.", "Lì non c’è nessun Pokémon.", "そこにポケモンはいません。", "그곳에는 포켓몬이 없습니다.", "Não há nenhum Pokémon aí."),
        ["Pokémon cambiados: {0} de {1}."] = ("Pokémon changed: {0} of {1}.", "已更改的宝可梦：{0} / {1}。", "Pokémon modifiés : {0} sur {1}.", "Geänderte Pokémon: {0} von {1}.", "Pokémon modificati: {0} su {1}.", "変更したポケモン：{1}匹中{0}匹。", "변경한 포켓몬: {1}마리 중 {0}마리.", "Pokémon alterados: {0} de {1}."),
        ["Con omisiones: {0}."] = ("With something skipped: {0}.", "有跳过项：{0}。", "Avec omissions : {0}.", "Mit Auslassungen: {0}.", "Con omissioni: {0}.", "スキップあり：{0}。", "건너뛴 항목 있음: {0}.", "Com omissões: {0}."),
        ["Lote deshecho: {0} Pokémon."] = ("Batch undone: {0} Pokémon.", "已撤销这批更改：{0} 只宝可梦。", "Lot annulé : {0} Pokémon.", "Stapel rückgängig gemacht: {0} Pokémon.", "Gruppo annullato: {0} Pokémon.", "一括変更を元に戻しました：{0}匹。", "일괄 변경을 되돌렸습니다: {0}마리.", "Lote desfeito: {0} Pokémon."),
        ["No hay ningún lote que deshacer."] = ("There is no batch to undo.", "没有可撤销的批量更改。", "Aucun lot à annuler.", "Kein Stapel zum Rückgängigmachen.", "Nessun gruppo da annullare.", "元に戻す一括変更はありません。", "되돌릴 일괄 변경이 없습니다.", "Não há nenhum lote para desfazer."),
        ["Ese reparto suma {0}. El máximo es {1}."] = ("That spread adds up to {0}. The maximum is {1}.", "该分配合计 {0}。上限为 {1}。", "Cette répartition totalise {0}. Le maximum est {1}.", "Diese Verteilung ergibt {0}. Das Maximum ist {1}.", "Quella distribuzione somma {0}. Il massimo è {1}.", "その配分の合計は {0} です。上限は {1} です。", "그 분배의 합계는 {0}입니다. 최대는 {1}입니다.", "Essa distribuição soma {0}. O máximo é {1}."),
        ["Un huevo no admite este cambio."] = ("An egg can't take this change.", "蛋无法进行此更改。", "Un œuf n’accepte pas cette modification.", "Ein Ei unterstützt diese Änderung nicht.", "Un uovo non accetta questa modifica.", "タマゴにはこの変更を適用できません。", "알에는 이 변경을 적용할 수 없습니다.", "Um ovo não aceita esta alteração."),
        ["Este juego no tiene Pokémon shiny."] = ("This game has no shiny Pokémon.", "此游戏没有异色宝可梦。", "Ce jeu n’a pas de Pokémon chromatiques.", "Dieses Spiel hat keine schillernden Pokémon.", "Questo gioco non ha Pokémon cromatici.", "このゲームに色違いのポケモンはいません。", "이 게임에는 색이 다른 포켓몬이 없습니다.", "Este jogo não tem Pokémon brilhantes."),
        ["Este juego no tiene amistad."] = ("This game has no friendship.", "此游戏没有亲密度。", "Ce jeu n’a pas d’amitié.", "Dieses Spiel hat keine Freundschaft.", "Questo gioco non ha l’amicizia.", "このゲームになつき度はありません。", "이 게임에는 친밀도가 없습니다.", "Este jogo não tem amizade."),
        ["Este juego no tiene Poké Balls que elegir."] = ("This game has no Poké Balls to choose from.", "此游戏没有可选择的精灵球。", "Ce jeu n’a pas de Poké Balls à choisir.", "Dieses Spiel hat keine Pokébälle zur Auswahl.", "Questo gioco non ha Poké Ball tra cui scegliere.", "このゲームには選べるモンスターボールがありません。", "이 게임에는 고를 수 있는 몬스터볼이 없습니다.", "Este jogo não tem Pokébolas para escolher."),
        ["Este juego no tiene objetos equipados."] = ("This game has no held items.", "此游戏没有携带道具。", "Ce jeu n’a pas d’objets tenus.", "Dieses Spiel hat keine getragenen Items.", "Questo gioco non ha strumenti tenuti.", "このゲームにはポケモンに持たせるどうぐがありません。", "이 게임에는 지니게 하는 도구가 없습니다.", "Este jogo não tem itens equipados."),
        ["Lleva una carta. Quítasela en el juego."] = ("It's holding mail. Take it off in the game.", "它携带着信件。请在游戏中取下。", "Il tient une lettre. Retirez-la dans le jeu.", "Es trägt einen Brief. Nimm ihn im Spiel ab.", "Tiene un messaggio. Toglilo nel gioco.", "メールを持っています。ゲーム内で外してください。", "메일을 지니고 있습니다. 게임에서 빼세요.", "Está com uma carta. Retire-a no jogo."),
        ["Su forma depende de ese objeto."] = ("Its form depends on that item.", "它的形态取决于该道具。", "Sa forme dépend de cet objet.", "Seine Form hängt von diesem Item ab.", "La sua forma dipende da quello strumento.", "そのどうぐでフォルムが決まります。", "그 도구에 따라 폼이 정해집니다.", "Sua forma depende desse item."),
        ["Ese objeto no tiene lugar en la bolsa."] = ("That item has no place in the bag.", "该道具在背包中没有位置。", "Cet objet n’a pas de place dans le sac.", "Dieses Item hat keinen Platz im Beutel.", "Quello strumento non ha posto nello zaino.", "そのどうぐを入れる場所がバッグにありません。", "그 도구를 넣을 자리가 가방에 없습니다.", "Esse item não tem lugar na mochila."),
        ["En Game Boy sus DV deciden su aspecto, y este cambio lo alteraría."] = ("On Game Boy its DVs decide how it looks, and this change would alter that.", "在 Game Boy 上，个体值决定其外观，此更改会改变外观。", "Sur Game Boy, ses DV décident de son apparence, et ce changement la modifierait.", "Auf dem Game Boy bestimmen die DV sein Aussehen, und diese Änderung würde es verändern.", "Su Game Boy i DV decidono il suo aspetto, e questa modifica lo altererebbe.", "ゲームボーイ版では個体値で見た目が決まるため、この変更で見た目が変わってしまいます。", "게임보이에서는 개체값이 모습을 결정하므로 이 변경을 하면 모습이 바뀝니다.", "No Game Boy, seus DVs decidem sua aparência, e esta alteração a mudaria."),
        // ---- legal-gen-03b4ce
        ["Generar desde Showdown…"] = ("Generate from Showdown…", "从 Showdown 生成…", "Générer depuis Showdown…", "Aus Showdown erzeugen…", "Genera da Showdown…", "Showdown から生成…", "Showdown에서 생성…", "Gerar do Showdown…"),
        ["Generar desde Showdown"] = ("Generate from Showdown", "从 Showdown 生成", "Générer depuis Showdown", "Aus Showdown erzeugen", "Genera da Showdown", "Showdown から生成", "Showdown에서 생성", "Gerar do Showdown"),
        ["Pokédex viviente…"] = ("Living Pokédex…", "活体图鉴…", "Pokédex vivant…", "Lebender Pokédex…", "Pokédex vivente…", "リビングデックス…", "리빙덱스…", "Pokédex viva…"),
        ["Pokédex viviente"] = ("Living Pokédex", "活体图鉴", "Pokédex vivant", "Lebender Pokédex", "Pokédex vivente", "リビングデックス", "리빙덱스", "Pokédex viva"),
        ["Generar"] = ("Generate", "生成", "Générer", "Erzeugen", "Genera", "生成", "생성", "Gerar"),
        ["Detener"] = ("Stop", "停止", "Arrêter", "Anhalten", "Ferma", "停止", "중지", "Parar"),
        ["Pegar del portapapeles"] = ("Paste from clipboard", "从剪贴板粘贴", "Coller depuis le presse-papiers", "Aus Zwischenablage einfügen", "Incolla dagli appunti", "クリップボードから貼り付け", "클립보드에서 붙여넣기", "Colar da área de transferência"),
        ["Colocar en las cajas"] = ("Place in the boxes", "放入盒子", "Placer dans les boîtes", "In die Boxen legen", "Metti nei box", "ボックスに配置", "박스에 배치", "Colocar nas caixas"),
        ["Pega aquí un set de Showdown…"] = ("Paste a Showdown set here…", "在此粘贴 Showdown 配置…", "Collez ici un set Showdown…", "Füge hier ein Showdown-Set ein…", "Incolla qui un set di Showdown…", "ここに Showdown のセットを貼り付けてください…", "여기에 Showdown 세트를 붙여넣으세요…", "Cole aqui um set do Showdown…"),
        ["Pega primero un set de Showdown."] = ("Paste a Showdown set first.", "请先粘贴 Showdown 配置。", "Collez d'abord un set Showdown.", "Füge zuerst ein Showdown-Set ein.", "Incolla prima un set di Showdown.", "先に Showdown のセットを貼り付けてください。", "먼저 Showdown 세트를 붙여넣으세요.", "Cole primeiro um set do Showdown."),
        ["Ese texto no es un set de Showdown."] = ("That text isn't a Showdown set.", "该文本不是 Showdown 配置。", "Ce texte n'est pas un set Showdown.", "Dieser Text ist kein Showdown-Set.", "Quel testo non è un set di Showdown.", "そのテキストは Showdown のセットではありません。", "그 텍스트는 Showdown 세트가 아닙니다.", "Esse texto não é um set do Showdown."),
        ["El set tiene líneas que no se entienden: {0}"] = ("The set has lines that can't be read: {0}", "该配置中有无法识别的行：{0}", "Le set contient des lignes illisibles : {0}", "Das Set hat Zeilen, die nicht gelesen werden können: {0}", "Il set ha righe illeggibili: {0}", "読み取れない行があります：{0}", "세트에 읽을 수 없는 줄이 있습니다: {0}", "O set tem linhas que não podem ser lidas: {0}"),
        ["Buscando un encuentro legal…"] = ("Looking for a legal encounter…", "正在查找合法的遭遇…", "Recherche d'une rencontre légale…", "Legale Begegnung wird gesucht…", "Ricerca di un incontro legale…", "正規の出会いを探しています…", "합법적인 만남을 찾는 중…", "Buscando um encontro legal…"),
        ["Generando {0} de {1}…"] = ("Generating {0} of {1}…", "正在生成 {0} / {1}…", "Génération de {0} sur {1}…", "Erzeuge {0} von {1}…", "Generazione di {0} su {1}…", "生成中 {0} / {1}…", "생성 중 {0} / {1}…", "Gerando {0} de {1}…"),
        ["Generación detenida."] = ("Generation stopped.", "生成已停止。", "Génération arrêtée.", "Erzeugung angehalten.", "Generazione fermata.", "生成を停止しました。", "생성을 중지했습니다.", "Geração interrompida."),
        ["Ningún encuentro legal da este Pokémon."] = ("No legal encounter gives this Pokémon.", "没有能得到此宝可梦的合法遭遇。", "Aucune rencontre légale ne donne ce Pokémon.", "Keine legale Begegnung ergibt dieses Pokémon.", "Nessun incontro legale dà questo Pokémon.", "このポケモンが手に入る正規の出会いがありません。", "이 포켓몬을 얻을 수 있는 합법적인 만남이 없습니다.", "Nenhum encontro legal dá este Pokémon."),
        ["Se agotó el tiempo de búsqueda."] = ("The search ran out of time.", "搜索超时。", "La recherche a expiré.", "Die Suche hat zu lange gedauert.", "La ricerca ha esaurito il tempo.", "検索がタイムアウトしました。", "검색 시간이 초과되었습니다.", "O tempo da busca esgotou."),
        ["El resultado no es legal: {0}"] = ("The result isn't legal: {0}", "结果不合法：{0}", "Le résultat n'est pas légal : {0}", "Das Ergebnis ist nicht legal: {0}", "Il risultato non è legale: {0}", "結果が正規ではありません：{0}", "결과가 합법이 아닙니다: {0}", "O resultado não é legal: {0}"),
        ["No se pudo generar: {0}"] = ("Couldn't generate it: {0}", "无法生成：{0}", "Génération impossible : {0}", "Konnte nicht erzeugt werden: {0}", "Generazione non riuscita: {0}", "生成できませんでした：{0}", "생성할 수 없습니다: {0}", "Não foi possível gerar: {0}"),
        ["{0} generado en {1}. Guarda para aplicarlo."] = ("{0} generated in {1}. Save to apply it.", "已在 {1} 生成 {0}。保存后生效。", "{0} généré dans {1}. Enregistrez pour l'appliquer.", "{0} in {1} erzeugt. Zum Anwenden speichern.", "{0} generato in {1}. Salva per applicarlo.", "{0} を {1} に生成しました。保存すると適用されます。", "{0}을(를) {1}에 생성했습니다. 저장하면 적용됩니다.", "{0} gerado em {1}. Salve para aplicar."),
        ["{0} generado en {1}."] = ("{0} generated in {1}.", "已在 {1} 生成 {0}。", "{0} généré dans {1}.", "{0} in {1} erzeugt.", "{0} generato in {1}.", "{0} を {1} に生成しました。", "{0}을(를) {1}에 생성했습니다.", "{0} gerado em {1}."),
        ["{0} solo es legal con {1}, y no hay en la bolsa."] = ("{0} is only legal with {1}, and the bag has none.", "{0} 只有携带 {1} 才合法，但背包中没有。", "{0} n'est légal qu'avec {1}, et le sac n'en contient pas.", "{0} ist nur mit {1} legal, und der Beutel hat keins.", "{0} è legale solo con {1}, e nello zaino non ce n’è.", "{0} は {1} がないと正規になりませんが、バッグにありません。", "{0}은(는) {1}이(가) 있어야 합법이지만 가방에 없습니다.", "{0} só é legal com {1}, e não há na mochila."),
        ["Omitido: {0}"] = ("Skipped: {0}", "已跳过：{0}", "Ignoré : {0}", "Übersprungen: {0}", "Saltato: {0}", "スキップ：{0}", "건너뜀: {0}", "Ignorado: {0}"),
        ["Busca un Pokémon legal de cada especie que te falte, en su forma base y a nivel 100. Nada cambia hasta que lo coloques."] = ("Looks for a legal Pokémon of each species you lack, in its base form and at level 100. Nothing changes until you place them.", "为你缺少的每种宝可梦查找一只合法个体，采用基础形态，等级 100。放入盒子之前不会有任何改变。", "Cherche un Pokémon légal de chaque espèce manquante, sous sa forme de base et au niveau 100. Rien ne change tant que vous ne les placez pas.", "Sucht ein legales Pokémon jeder fehlenden Art, in seiner Grundform und auf Level 100. Nichts ändert sich, bis du sie platzierst.", "Cerca un Pokémon legale per ogni specie che ti manca, nella forma base e al livello 100. Non cambia nulla finché non li metti nei box.", "足りない種族の正規のポケモンを、基本のフォルムのレベル100で探します。配置するまで何も変わりません。", "없는 종마다 합법적인 포켓몬을 기본 폼, 레벨 100으로 찾습니다. 배치하기 전까지는 아무것도 바뀌지 않습니다.", "Busca um Pokémon legal de cada espécie que falta, na forma base e no nível 100. Nada muda até você colocá-los."),
        ["Ya tienes todas las especies de este juego."] = ("You already have every species in this game.", "你已拥有此游戏的所有宝可梦。", "Vous avez déjà toutes les espèces de ce jeu.", "Du hast bereits alle Arten dieses Spiels.", "Hai già tutte le specie di questo gioco.", "このゲームの種族はすべて持っています。", "이 게임의 모든 종을 이미 가지고 있습니다.", "Você já tem todas as espécies deste jogo."),
        ["Listos: {0}. Omitidos: {1}."] = ("Ready: {0}. Skipped: {1}.", "就绪：{0}。已跳过：{1}。", "Prêts : {0}. Ignorés : {1}.", "Bereit: {0}. Übersprungen: {1}.", "Pronti: {0}. Saltati: {1}.", "準備完了：{0}。スキップ：{1}。", "준비됨: {0}. 건너뜀: {1}.", "Prontos: {0}. Ignorados: {1}."),
        ["Sin sitio en las cajas: {0}."] = ("No room in the boxes: {0}.", "盒子放不下：{0}。", "Sans place dans les boîtes : {0}.", "Kein Platz in den Boxen: {0}.", "Senza posto nei box: {0}.", "ボックスに空きなし：{0}。", "박스에 자리 없음: {0}.", "Sem espaço nas caixas: {0}."),
        ["Ya en la partida: {0}."] = ("Already in the save: {0}.", "存档中已有：{0}。", "Déjà dans la partie : {0}.", "Bereits im Spielstand: {0}.", "Già nella partita: {0}.", "すでにセーブデータ内：{0}。", "이미 세이브에 있음: {0}.", "Já no save: {0}."),
        ["Pokémon colocados: {0}. Guarda para aplicarlos, o quítalos todos con «Deshacer el último cambio de cajas»."] = ("Pokémon placed: {0}. Save to apply them, or remove them all with “Undo the last box change”.", "已放入的宝可梦：{0}。保存后生效，或使用“撤销上一次盒子更改”全部移除。", "Pokémon placés : {0}. Enregistrez pour les appliquer, ou retirez-les tous avec « Annuler le dernier changement de boîtes ».", "Pokémon platziert: {0}. Zum Anwenden speichern, oder entferne alle mit „Letzte Box-Änderung rückgängig machen“.", "Pokémon messi nei box: {0}. Salva per applicarlo, o toglili tutti con «Annulla l’ultima modifica ai box».", "ポケモンを配置しました：{0}。保存すると適用されます。「最後のボックスの変更を元に戻す」ですべて取り除けます。", "포켓몬을 배치했습니다: {0}. 저장하면 적용되며, ‘마지막 박스 변경 되돌리기’로 모두 없앨 수 있습니다.", "Pokémon colocados: {0}. Salve para aplicar ou remova todos com “Desfazer a última alteração nas caixas”."),
        // ---- game-extras-55ecb5
        ["El nombre de una caja no puede quedar vacío."] = ("A box name can't be empty.", "盒子名称不能为空。", "Le nom d’une boîte ne peut pas être vide.", "Der Name einer Box darf nicht leer sein.", "Il nome di un box non può restare vuoto.", "ボックスの名前は空にできません。", "박스 이름은 비워 둘 수 없습니다.", "O nome de uma caixa não pode ficar vazio."),
        ["El nombre de una caja admite hasta {0} caracteres."] = ("A box name can have up to {0} characters.", "盒子名称最多 {0} 个字符。", "Le nom d’une boîte peut contenir jusqu’à {0} caractères.", "Der Name einer Box darf bis zu {0} Zeichen haben.", "Il nome di un box può avere fino a {0} caratteri.", "ボックスの名前は{0}文字までです。", "박스 이름은 최대 {0}자입니다.", "O nome de uma caixa aceita até {0} caracteres."),
        ["En este juego la guardería solo se puede consultar: PKHeX no sabe vaciar sus lugares."] = ("In this game the daycare can only be viewed: PKHeX can't empty its places.", "此游戏的培育屋只能查看：PKHeX 无法清空其位置。", "Dans ce jeu, la pension peut seulement être consultée : PKHeX ne sait pas vider ses places.", "In diesem Spiel kann die Pension nur angesehen werden: PKHeX kann ihre Plätze nicht leeren.", "In questo gioco la pensione si può solo consultare: PKHeX non sa svuotarne i posti.", "このゲームでは育て屋は閲覧のみです。PKHeX では枠を空にできません。", "이 게임에서 키우미집은 보기만 할 수 있습니다. PKHeX는 자리를 비울 수 없습니다.", "Neste jogo, a creche só pode ser consultada: o PKHeX não sabe esvaziar seus lugares."),
        ["Ese Pokémon tiene datos dañados."] = ("That Pokémon has damaged data.", "该宝可梦的数据已损坏。", "Ce Pokémon a des données endommagées.", "Dieses Pokémon hat beschädigte Daten.", "Quel Pokémon ha dati danneggiati.", "そのポケモンのデータは破損しています。", "그 포켓몬의 데이터가 손상되었습니다.", "Esse Pokémon tem dados danificados."),
        ["Hay un huevo esperando. Recógelo en el juego antes de sacar a sus padres."] = ("An egg is waiting. Collect it in the game before taking its parents out.", "有一颗蛋在等待。请先在游戏中领取，再带走它的父母。", "Un œuf attend. Récupérez-le dans le jeu avant de retirer ses parents.", "Ein Ei wartet. Hole es im Spiel ab, bevor du die Eltern herausnimmst.", "C’è un uovo in attesa. Ritiralo nel gioco prima di togliere i genitori.", "タマゴが待っています。親を引き取る前にゲーム内で受け取ってください。", "알이 기다리고 있습니다. 부모를 꺼내기 전에 게임에서 받으세요.", "Há um ovo esperando. Pegue-o no jogo antes de retirar os pais."),
        ["Huevo de {0}"] = ("{0} Egg", "{0}的蛋", "Œuf de {0}", "{0}-Ei", "Uovo di {0}", "{0}のタマゴ", "{0}의 알", "Ovo de {0}"),
