        ["Dejar en la guardería"] = ("Leave in the daycare", "留在培育屋", "Laisser à la pension", "In der Pension lassen", "Lascia in pensione", "育て屋に預けたままにする", "키우미집에 두기", "Deixar na creche"),
        ["{0} se queda en la guardería."] = ("{0} stays in the daycare.", "{0} 留在培育屋。", "{0} reste à la pension.", "{0} bleibt in der Pension.", "{0} resta in pensione.", "{0} は育て屋に残ります。", "{0}은(는) 키우미집에 남습니다.", "{0} fica na creche."),
        ["No hay ningún Pokémon en la guardería."] = ("There are no Pokémon in the daycare.", "培育屋里没有宝可梦。", "Il n’y a aucun Pokémon à la pension.", "In der Pension ist kein Pokémon.", "Non c’è nessun Pokémon in pensione.", "育て屋にポケモンはいません。", "키우미집에 포켓몬이 없습니다.", "Não há nenhum Pokémon na creche."),
        ["Sale como entró, sin la experiencia que haya ganado allí, y llega al primer lugar libre desde la caja abierta."] = ("It leaves as it went in, without the experience it gained there, and arrives in the first free place from the open box on.", "它会以寄放时的状态离开，不含在那里获得的经验值，并进入从当前盒子起的第一个空位。", "Il repart tel qu’il est entré, sans l’expérience gagnée là-bas, et arrive à la première place libre à partir de la boîte ouverte.", "Es kommt so heraus, wie es hineinging, ohne die dort gewonnene Erfahrung, und landet auf dem ersten freien Platz ab der offenen Box.", "Esce com’era entrato, senza l’esperienza guadagnata lì, e arriva nel primo posto libero a partire dal box aperto.", "預けたときの状態で戻り、育て屋で得た経験値は入りません。開いているボックスから順に最初の空きに入ります。", "맡겼을 때 그대로 나오며 그곳에서 얻은 경험치는 없습니다. 열린 박스부터 첫 빈자리에 들어갑니다.", "Sai como entrou, sem a experiência que ganhou lá, e vai para o primeiro lugar livre a partir da caixa aberta."),
        ["Hay un huevo de {0} esperando."] = ("A {0} Egg is waiting.", "有一颗{0}的蛋在等待。", "Un œuf de {0} attend.", "Ein {0}-Ei wartet.", "C’è un Uovo di {0} in attesa.", "{0}のタマゴが待っています。", "{0}의 알이 기다리고 있습니다.", "Há um ovo de {0} esperando."),
        ["Hay un huevo esperando."] = ("An egg is waiting.", "有一颗蛋在等待。", "Un œuf attend.", "Ein Ei wartet.", "C’è un uovo in attesa.", "タマゴが待っています。", "알이 기다리고 있습니다.", "Há um ovo esperando."),
        ["No hay ningún huevo esperando."] = ("No egg is waiting.", "没有等待领取的蛋。", "Aucun œuf n’attend.", "Es wartet kein Ei.", "Nessun uovo in attesa.", "待っているタマゴはありません。", "기다리는 알이 없습니다.", "Nenhum ovo esperando."),
        ["Guardería {0}: hay un huevo esperando."] = ("Daycare {0}: an egg is waiting.", "培育屋 {0}：有一颗蛋在等待。", "Pension {0} : un œuf attend.", "Pension {0}: Ein Ei wartet.", "Pensione {0}: c’è un uovo in attesa.", "育て屋 {0}：タマゴが待っています。", "키우미집 {0}: 알이 기다리고 있습니다.", "Creche {0}: há um ovo esperando."),
        ["Guardería {0}: sin huevo."] = ("Daycare {0}: no egg.", "培育屋 {0}：没有蛋。", "Pension {0} : pas d’œuf.", "Pension {0}: kein Ei.", "Pensione {0}: nessun uovo.", "育て屋 {0}：タマゴなし。", "키우미집 {0}: 알 없음.", "Creche {0}: sem ovo."),
        ["Lugar {0}"] = ("Place {0}", "位置 {0}", "Place {0}", "Platz {0}", "Posto {0}", "枠 {0}", "자리 {0}", "Lugar {0}"),
        ["Guardería {0} · Lugar {1}"] = ("Daycare {0} · Place {1}", "培育屋 {0} · 位置 {1}", "Pension {0} · Place {1}", "Pension {0} · Platz {1}", "Pensione {0} · Posto {1}", "育て屋 {0} · 枠 {1}", "키우미집 {0} · 자리 {1}", "Creche {0} · Lugar {1}"),
        ["Sale a {0}"] = ("Leaves for {0}", "前往 {0}", "Part vers {0}", "Geht nach {0}", "Va a {0}", "{0} へ移動", "{0}(으)로 나감", "Vai para {0}"),
        ["En la guardería"] = ("In the daycare", "在培育屋", "À la pension", "In der Pension", "In pensione", "育て屋にいる", "키우미집에 있음", "Na creche"),
        ["Deshacer regalos"] = ("Undo gifts", "撤销礼物", "Annuler les cadeaux", "Geschenke zurücksetzen", "Annulla regali", "おくりものを元に戻す", "선물 되돌리기", "Desfazer presentes"),
        ["N.º de regalo"] = ("Gift no.", "礼物编号", "N° de cadeau", "Geschenk-Nr.", "N. regalo", "おくりもの No.", "선물 번호", "N.º do presente"),
        ["Regalo"] = ("Gift", "礼物", "Cadeau", "Geschenk", "Regalo", "おくりもの", "선물", "Presente"),
        ["Recibido"] = ("Received", "已领取", "Reçu", "Erhalten", "Ricevuto", "受け取り済み", "받음", "Recebido"),
        ["Esta partida no recuerda ningún regalo."] = ("This save remembers no gifts.", "此存档没有礼物记录。", "Cette partie ne garde aucun cadeau en mémoire.", "Dieser Spielstand kennt keine Geschenke.", "Questa partita non ricorda nessun regalo.", "このセーブデータにおくりものの記録はありません。", "이 세이브에는 받은 선물 기록이 없습니다.", "Este save não lembra nenhum presente."),
        ["Quitar la marca borra el regalo de la lista y la señal de recibido, para que el juego pueda entregarlo otra vez."] = ("Clearing the tick removes the gift from the list and its received mark, so the game can give it again.", "取消勾选会从列表中删除该礼物及其已领取标记，游戏便可再次发放。", "Décocher retire le cadeau de la liste et sa marque de réception, pour que le jeu puisse le redonner.", "Entfernst du das Häkchen, verschwindet das Geschenk samt Empfangsmarke aus der Liste, sodass das Spiel es erneut geben kann.", "Togliere il segno cancella il regalo dall’elenco insieme al segno di ricevuto, così il gioco può consegnarlo di nuovo.", "チェックを外すと、おくりものが一覧と受け取り済みの印から消え、ゲームでもう一度受け取れます。", "표시를 지우면 선물이 목록과 받음 표시에서 사라져 게임에서 다시 받을 수 있습니다.", "Desmarcar apaga o presente da lista e a marca de recebido, para que o jogo possa entregá-lo de novo."),
        ["Quitar la marca borra el regalo de la lista. Este registro no está documentado en PKHeX y no se ha comprobado en el juego que baste para recibirlo otra vez."] = ("Clearing the tick removes the gift from the list. PKHeX doesn't document this record, and it hasn't been tested in the game whether that is enough to receive it again.", "取消勾选会从列表中删除该礼物。PKHeX 没有记载此记录的格式，也尚未在游戏中验证这样能否再次领取。", "Décocher retire le cadeau de la liste. PKHeX ne documente pas ce registre, et il n’a pas été vérifié en jeu que cela suffise pour le recevoir de nouveau.", "Entfernst du das Häkchen, verschwindet das Geschenk aus der Liste. PKHeX dokumentiert dieses Register nicht, und im Spiel wurde nicht geprüft, ob das reicht, um es erneut zu erhalten.", "Togliere il segno cancella il regalo dall’elenco. PKHeX non documenta questo registro, e non è stato verificato nel gioco se basti per riceverlo di nuovo.", "チェックを外すと一覧からおくりものが消えます。この記録は PKHeX に説明がなく、もう一度受け取れるかはゲームで確認していません。", "표시를 지우면 선물이 목록에서 사라집니다. 이 기록은 PKHeX에 설명이 없으며, 이것만으로 다시 받을 수 있는지는 게임에서 확인하지 않았습니다.", "Desmarcar apaga o presente da lista. O PKHeX não documenta este registro, e não foi testado no jogo se isso basta para recebê-lo de novo."),
        ["Entrada"] = ("Entry", "条目", "Entrée", "Eintrag", "Voce", "記録", "기록", "Entrada"),
        ["Esta partida aún no tiene entradas."] = ("This save has no entries yet.", "此存档还没有条目。", "Cette partie n’a pas encore d’entrées.", "Dieser Spielstand hat noch keine Einträge.", "Questa partita non ha ancora voci.", "このセーブデータにはまだ記録がありません。", "이 세이브에는 아직 기록이 없습니다.", "Este save ainda não tem entradas."),
        ["Este juego solo guarda las especies de la primera vez y de la última."] = ("This game only keeps the species of the first time and the latest.", "此游戏只保存首次和最近一次的宝可梦种类。", "Ce jeu ne garde que les espèces de la première fois et de la dernière.", "Dieses Spiel speichert nur die Arten des ersten und des letzten Mals.", "Questo gioco conserva solo le specie della prima e dell’ultima volta.", "このゲームには最初と最新の種族だけが記録されます。", "이 게임은 처음과 최근의 종만 저장합니다.", "Este jogo só guarda as espécies da primeira e da última vez."),
        ["Este juego solo guarda el día de la primera vez."] = ("This game only keeps the day of the first time.", "此游戏只保存首次的日期。", "Ce jeu ne garde que le jour de la première fois.", "Dieses Spiel speichert nur den Tag des ersten Mals.", "Questo gioco conserva solo il giorno della prima volta.", "このゲームには最初の日付だけが記録されます。", "이 게임은 처음 날짜만 저장합니다.", "Este jogo só guarda o dia da primeira vez."),
        ["Aquí solo se consulta: nada de esto cambia la partida."] = ("This is only to look at: nothing here changes the save.", "这里仅供查看，不会更改存档。", "Ceci est en lecture seule : rien ici ne modifie la partie.", "Nur zum Ansehen: Nichts hier ändert den Spielstand.", "Solo consultazione: nulla di tutto ciò cambia la partita.", "閲覧専用です。ここではセーブデータは変わりません。", "보기 전용입니다. 여기서는 세이브가 바뀌지 않습니다.", "Só para consulta: nada aqui muda o save."),
